        "Cho đến khi được khám, hãy dùng băng vệ sinh, không dùng tampon, để biết mình ra máu bao nhiêu. Nghỉ ngơi nhiều như bạn thấy cần. Vận động, làm việc và quan hệ tình dục không gây sẩy thai.",
        "Thai ngoài tử cung",
