        "Gọi bác sĩ gia đình, bác sĩ sản hoặc nữ hộ sinh nếu bạn có",
        "Ngứa lòng bàn tay hoặc bàn chân · Ngứa khắp người đến mất ngủ · Nước tiểu sẫm màu hoặc phân bạc màu · Da hoặc mắt vàng",
